#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

fail() {
  printf 'FAIL: %s\n' "$1" >&2
  exit 1
}

require_contains() {
  local file="$1"
  local text="$2"

  grep -Fq "$text" "$ROOT_DIR/$file" || fail "$file is missing required text: $text"
}

require_not_contains() {
  local file="$1"
  local text="$2"

  if grep -Fq "$text" "$ROOT_DIR/$file"; then
    fail "$file contains forbidden text: $text"
  fi
}

# incu-way-init must always ensure .claude/ and .agents/ are gitignored — every bit of
# their content is regenerated by `ways install` from the locks, never source of truth.
require_contains "skills/incu-way-init/SKILL.md" ".claude/"
require_contains "skills/incu-way-init/SKILL.md" ".agents/"

# .ways/ must never be blanket-ignored — state.json is committed (resume-by-branch).
require_contains "skills/incu-way-init/SKILL.md" "Never blanket-ignore \`.ways/\`."
if grep -Fxq '.ways/' "$ROOT_DIR/skills/incu-way-init/SKILL.md"; then
  fail "skills/incu-way-init/SKILL.md has a bare '.ways/' gitignore entry (must be .ways/cache/ only)"
fi

printf 'PASS: gitignore hygiene (.claude/, .agents/ ignored; .ways/ never blanket-ignored)\n'
